mapper.select:
SELECT w.*,p.title parent_title FROM wbs_item w LEFT JOIN wbs_item p ON p.id=w.parent_id
WHERE w.project_id=#{projectId}
ORDER BY COALESCE(w.parent_id,w.id),CASE WHEN w.parent_id IS NULL THEN 0 ELSE 1 END,w.id

mapper.update:
UPDATE source_scan SET status=#{status},language=#{language},framework=#{framework},file_count=#{fileCount},
code_issue_count=#{codeIssueCount},security_issue_count=#{securityIssueCount}
WHERE project_id=#{projectId} AND id=#{scanId}

UPDATE standard_term SET standard_word=#{standardWord},match_status=#{matchStatus},
recommendation=#{recommendation},review_memo=#{reviewMemo},excluded=#{excluded}
WHERE project_id=#{projectId} AND id=#{termId}

mapper.insert:
INSERT INTO db_table(db_model_id,name,description,primary_key_name)
SELECT #{modelId},#{name},#{description},#{primaryKeyName} FROM db_model
WHERE id=#{modelId} AND project_id=#{projectId}

INSERT INTO db_column(db_table_id,name,data_type,nullable,default_value,is_primary,is_unique,is_indexed,description)
SELECT #{tableId},#{name},#{dataType},#{nullable},#{defaultValue},#{isPrimary},#{isUnique},#{isIndexed},#{description}
FROM db_table t JOIN db_model m ON m.id=t.db_model_id WHERE t.id=#{tableId} AND m.project_id=#{projectId}

INSERT INTO db_relation(db_model_id,from_table_id,to_table_id,relation_type,from_column,to_column,description)
SELECT #{modelId},#{fromTableId},#{toTableId},#{relationType},#{fromColumn},#{toColumn},#{description}
FROM db_model m WHERE m.id=#{modelId} AND m.project_id=#{projectId}
AND EXISTS(SELECT 1 FROM db_table ft WHERE ft.id=#{fromTableId} AND ft.db_model_id=m.id)
AND EXISTS(SELECT 1 FROM db_table tt WHERE tt.id=#{toTableId} AND tt.db_model_id=m.id)

INSERT INTO sample_dataset_item(sample_dataset_id,item_key,item_value_json)
SELECT #{datasetId},#{itemKey},#{itemValueJson} FROM sample_dataset
WHERE id=#{datasetId} AND project_id=#{projectId}
